@register_cmd("ping")
async def cmd_ping(event, _):
    try:
        t0 = time.perf_counter()

        # ─── MESSAGE DISPATCH SAFE ───
        try:
            if event.out:
                msg = await event.edit("🏓 𝐏ɪɴɢ...")
            else:
                msg = await event.reply("🏓 𝐏ɪɴɢ...")
        except:
            msg = None

        t1 = time.perf_counter()
        ms = round((t1 - t0) * 1000)

        # ─── RESPONSE EDIT SAFE ───
        try:
            if msg:
                await msg.edit(f"🏓 𝐏ᴏɴɢ → `{ms} ms`\n👑 𝐁𝐋𝐎𝐎𝐃 𝐕𝐎𝐑𝐓𝐄𝐗\n💎 𝐏ᴏᴡᴇʀᴇᴅ ʙʏ @BLOOD_VORTEX_1")
            else:
                await event.reply(f"🏓 𝐏ᴏɴɢ → `{ms} ms`\n👑 𝐁𝐋𝐎𝐎𝐃 𝐕𝐎𝐑𝐓𝐄𝐗\n💎 𝐏ᴏᴡᴇʀᴇᴅ ʙʏ @BLOOD_VORTEX_1")
        except:
            pass

    except FloodWaitError as fw:
        await safe_edit(event, f"⏳ 𝐅ʟᴏᴏᴅ → {fw.seconds}s")
    except Exception as e:
        await safe_edit(event, f"❌ 𝐏ɪɴɢ 𝐄ʀʀ → `{str(e)[:40]}`")


