    try:

        # ⭐ REACTION ENGINE
        await bot(functions.messages.SendReactionRequest(
            peer=chat,
            msg_id=msg_id,
            reaction=[
                types.ReactionEmoji(
                    emoticon=emoji
                )
            ]
        ))

    except FloodWaitError as fw:
        try:
            await asyncio.sleep(fw.seconds)
        except:
            pass

    except RPCError:
        # ⭐ silent rpc fail safe
        pass

    except Exception:
        # ⭐ unknown crash isolation
        pass

