async def _vortex_animation(event, frames, delay=0.65):
    """Edit one message through a short animation; falls back to final frame."""
    try:
        if getattr(event, "out", False):
            msg = await event.edit(frames[0])
        else:
            msg = await event.reply(frames[0])
        for frame in frames[1:]:
            await asyncio.sleep(delay)
            await msg.edit(frame)
    except Exception:
        try:
            await safe_edit(event, frames[-1])
        except Exception:
            pass

