# ────────────────────────────────────────────────
#                   START
# ────────────────────────────────────────────────
async def main():
    music_app = None
    music_player = None
    try:
        # Optional Pyrogram music bot runs beside the existing Telethon userbot.
        bot_token = os.getenv("BOT_TOKEN", "").strip()
        if bot_token:
            from pyrogram import Client as PyrogramClient
            from music import music_player as _music_player
            from music.handlers import register_music_handlers

            music_player = _music_player
            music_app = PyrogramClient(
                "roh4n_music_bot",
                api_id=API_ID,
                api_hash=API_HASH,
                bot_token=bot_token,
                in_memory=True,
            )
            register_music_handlers(music_app)
            await music_app.start()
            print("🎵 Music command bot started")
            try:
                await music_player.start(music_app)
            except Exception as exc:
                print(f"⚠️ Music engine did not start: {exc}")
        else:
            print("ℹ️ BOT_TOKEN not set; music bot is disabled")

        # Start the existing Telethon userbot.
        await bot.start()
        me = await bot.get_me()
        uname = f"@{me.username}" if me.username else "NoUsername"
        print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
        print("🤖 USERBOT STARTED SUCCESSFULLY")
        print(f"👤 Logged in as → {me.first_name} ({uname})")
        print(f"🆔 User ID → {me.id}")
        print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━")

        while True:
            try:
                await bot.run_until_disconnected()
                break
            except (ConnectionError, OSError):
                print("⚠️ Connection Lost → Reconnecting...")
                await asyncio.sleep(3)

    except KeyboardInterrupt:
        print("\n🛑 Userbot stopped manually")
    except Exception as exc:
        print(f"\n❌ Startup Error → {str(exc)[:160]}")
        traceback.print_exc()
    finally:
        if music_player:
            try:
                await music_player.stop()
            except Exception:
                pass
        if music_app:
            try:
                await music_app.stop()
            except Exception:
                pass
        try:
            if bot.is_connected():
                await bot.disconnect()
        except Exception:
            pass


if __name__ == "__main__":
    asyncio.run(main())
